const e=JSON.parse('{"key":"v-90e86292","path":"/ACM-docs/%E6%95%B0%E5%AD%A6/%E5%8D%9A%E5%BC%88%E8%AE%BA/%E7%BB%8F%E5%85%B8%E5%8D%9A%E5%BC%88.html","title":"经典博弈","lang":"zh-CN","frontmatter":{"summary":"经典博弈 巴什博弈（Bash Game） \\" 一堆$n$个物品，两个人轮流从中取出$1~m$个，最后取光者胜（不能继续取的人输）。\\" 同余定理：$n=k∗(m+1)+r$，先者拿走$r$个，那么后者无论拿走$1 m$个先者只要的数目使和为$m+1$，那么先手必赢。反之若$n=k∗(m+1)$，那么先手无论怎样都会输。 斐波那契博弈（Fibonacci Nim","head":[["meta",{"property":"og:url","content":"https://ClearDewy.github.io/ACM-docs/%E6%95%B0%E5%AD%A6/%E5%8D%9A%E5%BC%88%E8%AE%BA/%E7%BB%8F%E5%85%B8%E5%8D%9A%E5%BC%88.html"}],["meta",{"property":"og:site_name","content":"Dewy-Wiki"}],["meta",{"property":"og:title","content":"经典博弈"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:updated_time","content":"2022-11-09T02:09:26.000Z"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"article:modified_time","content":"2022-11-09T02:09:26.000Z"}]]},"excerpt":"","headers":[{"level":2,"title":"巴什博弈（Bash Game）","slug":"巴什博弈-bash-game","link":"#巴什博弈-bash-game","children":[]},{"level":2,"title":"斐波那契博弈（Fibonacci Nim Game）","slug":"斐波那契博弈-fibonacci-nim-game","link":"#斐波那契博弈-fibonacci-nim-game","children":[]},{"level":2,"title":"威佐夫博弈（Wythoff Game）","slug":"威佐夫博弈-wythoff-game","link":"#威佐夫博弈-wythoff-game","children":[]},{"level":2,"title":"尼姆博弈（Nimm Game）","slug":"尼姆博弈-nimm-game","link":"#尼姆博弈-nimm-game","children":[]}],"git":{"createdTime":1667959766000,"updatedTime":1667959766000,"contributors":[{"name":"ClearDewy","email":"2233408834@qq.com","commits":1}]},"readingTime":{"minutes":1.15,"words":344},"filePathRelative":"ACM-docs/数学/博弈论/经典博弈.md","localizedDate":"2022年11月9日"}');export{e as data};
